@Service
public class BatchProcessor {

    @Autowired
    private JobLauncher jobLauncher;

    @Autowired
    private JobRepository jobRepository;

    @Autowired
    private JobRegistry jobRegistry;

    public void processBatch() {
        // Create a new job instance
        Job job = jobRegistry.getJob("myJob");

        // Create a new job parameters
        JobParameters jobParameters = new JobParametersBuilder()
                .addString("inputFile", "input.txt")
                .toJobParameters();

        // Launch the job
        try {
            JobExecution execution = jobLauncher.run(job, jobParameters);
            // Process the job execution
            processJobExecution(execution);
        } catch (JobExecutionAlreadyRunningException e) {
            // Handle the exception
        } catch (JobRestartException e) {
            // Handle the exception
        } catch (JobInstanceAlreadyExistsException e) {
            // Handle the exception
        } catch (JobParametersInvalidException e) {
            // Handle the exception
        }
    }

    private void processJobExecution(JobExecution execution) {
        // Process the job execution
        // For example, you can get the job parameters
        JobParameters jobParameters = execution.getJobParameters();
        // Get the job parameters
        String inputFile = jobParameters.getString("inputFile");
        // Process the input file
        // For example, you can read the file and process its content
        File file = new File(inputFile);
        // Read the file
        Scanner scanner = new Scanner(file);
        // Process the file content
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            // Process the line
            System.out.println(line);
        }
        scanner.close();
    }
}
